"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[4093],{82203:e=>{e.exports=JSON.parse('{"functions":[{"name":"registerCallback","desc":"Registers a fulfilment callback for products matching `event`.\\n\\nWhen a receipt is processed, [MarketplaceService] runs **every** callback\\nwhose filter matches the product \u2014 registration order, no short-circuiting.\\nA callback returning a falsy value fails the whole receipt, which is then\\nleft `NotProcessedYet` so Roblox retries it later; grants must therefore be\\nidempotent.\\n\\nThe callback receives the receipt, the product definition, any pending\\npurchase data staged for that product/player pair, and the player.\\n\\n```lua\\nMarketplaceData.registerCallback({ type = \\"coins\\" }, function(receiptInfo, product)\\n\\tlocal player = Players:GetPlayerByUserId(receiptInfo.PlayerId)\\n\\treturn player and CurrencyService.add(player, \\"coins\\", product.value)\\nend)\\n```","params":[{"name":"event","desc":"filter deciding which products this handles","lua_type":"MarketplaceEvent"},{"name":"callback","desc":"fulfilment, truthy on success","lua_type":"(Types.ReceiptInfo, Types.DevProduct, any, Player) -> boolean?"}],"returns":[],"function_type":"static","source":{"line":73,"path":"src/Server/Features/Shop/MarketplaceData.luau"}}],"properties":[],"types":[{"name":"MarketplaceEvent","desc":"The filter a registered callback is matched against. A nil field is a\\nwildcard, so `{ type = \\"coins\\" }` runs for every coin product regardless of\\naction.","fields":[{"name":"type","lua_type":"string?","desc":"product type to match, e.g. \\"coins\\" or \\"item\\"; nil matches any"},{"name":"action","lua_type":"string?","desc":"product action to match; nil matches any"}],"source":{"line":31,"path":"src/Server/Features/Shop/MarketplaceData.luau"}}],"name":"MarketplaceData","desc":"The receipt-callback registry shared between [MarketplaceService] and the\\nservices that fulfil purchases.\\n\\nExists as a separate module purely to break a require cycle: fulfilment\\nservices ([CurrencyService], [ShopService]) register here at init, and\\n[MarketplaceService] reads the list when a receipt arrives, so neither has to\\nrequire the other.\\n\\nCopyright (c) 2026 firebit. All rights reserved.\\nfirebit/survival-islands - proprietary and confidential.","realm":["Server"],"source":{"line":16,"path":"src/Server/Features/Shop/MarketplaceData.luau"}}')}}]);